"""Builds llm_log/log_full.csv from the batch logs + manual entries. python scripts/make_llm_log.py"""
import csv, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent; rows = []
def add(path, version, purpose, decision):
    for r in csv.DictReader(open(path, encoding="utf-8")): rows.append(dict(date=r["date"], model=r["model"], parameters=r["parameters"], prompt_version=version, purpose=purpose, input=f"{path.parent.name}/in/{r['batch']}.json#{r['key12']}", raw_output=f"{path.parent.name}/raw/{r['batch']}.json#{r['key12']}", raw_chars=r["raw_chars"], human_decision=decision))
add(ROOT / "llm_log/v1/log.csv", "explain-v1 (labels without id)", "paraphrase of a path-based recommendation explanation", "superseded: labels were ambiguous (several chunks share one section heading); output not used in eval/explanations.json")
add(ROOT / "llm_log/log.csv", "explain-v2 (labels 'id · heading')", "paraphrase of a path-based recommendation explanation", "accepted when reco.explain.check passed (100/100 did); reviewer = LLM assistant, human V3 spot-check pending")
rows.append(dict(date="2026-11-08", model="claude-sonnet-5-5 (subagent)", parameters="temperature=default(not controllable); seed=n/a", prompt_version="metrics_extraction_v1", purpose="extract headline numbers from lab 5-15 reports for the white paper", input="llm_log/prompts/metrics_extraction_v1.txt", raw_output="claims/sources/lab_metrics_extract.md", raw_chars="", human_decision="used for claims c15-c24 only after V1 string check against the report text; one extraction paraphrase (Lab 12 '22/22' vs report '22 з 22') was caught and corrected"))
rows.append(dict(date="2026-11-08", model="claude-sonnet-5-5 (main assistant)", parameters="not controllable", prompt_version="n/a (interactive session)", purpose="drafting code, docs/*.md, white paper text, report", input="session transcript", raw_output="repository history", raw_chars="", human_decision="every number is generated from eval/*.json by scripts; statements about regulation verified on the web (c25-c31); the author must still review (V3)"))
rows.append(dict(date="2026-11-08", model="claude-sonnet-5-5 (main assistant)", parameters="not controllable", prompt_version="n/a", purpose="regulatory facts (AI Act dates, NIST AI RMF) via WebSearch/WebFetch", input="queries in claims.csv sources", raw_output="claims/claims.csv c25-c32", raw_chars="", human_decision="LLM memory said Annex III applies from 2 Aug 2026 (c29) -> rejected after the web check (Digital Omnibus: 2 Dec 2027, c28)"))
with open(ROOT / "llm_log/log_full.csv", "w", newline="", encoding="utf-8") as f: w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
print(len(rows), "log rows")
